import stylesText from './frequent-grid.css?inline';
import { cssStyleSheet } from '../../../../utils/css.js';

const styles = cssStyleSheet(stylesText);
import { MEAL_TYPES } from '@motivation/shared';
import type { FrequentEntry, MealType } from '@motivation/shared';
import { HealthService } from '../../../../services/health.service.js';
import { createSelectLibraryItemEvent, createSelectMealEvent } from '../../health-events.js';
import '../../food-thumbnail/food-thumbnail.component.js';

const TILE_LIMIT = 24;

const template = document.createElement('template');
template.innerHTML = `
    <div id="wrapper" hidden>
        <div class="frequent-grid" id="grid"></div>
        <pre class="frequent-error" id="error" hidden></pre>
    </div>
`;

/**
 * Story 276 — one-tap tiles for the items most logged into the meal slot being
 * logged, mixing food items and meal templates.
 *
 * Tapping a tile emits the same `SELECT_LIBRARY_ITEM` / `SELECT_MEAL` events a
 * search-result row emits, so the screen routes it through the existing detail
 * view: this component adds a shortcut, never a second logging path.
 *
 * Visibility has two independent owners, deliberately: the *host* is hidden by
 * `<food-log>` when search results take over, while the inner wrapper is hidden
 * by this component when the slot has no history. An empty slot renders nothing
 * at all — no empty-state copy (AC: "no grid, no error").
 *
 * Story 284 dropped the "Often for {slot}" heading: the tiles say what they are,
 * and the screen already names the slot.
 */
export class FrequentGrid extends HTMLElement {
    static readonly observedAttributes = ['meal-type'];

    private loadSeq = 0;

    constructor() {
        super();
        const shadow = this.attachShadow({ mode: 'open' });
        shadow.adoptedStyleSheets = [styles];
        shadow.appendChild(template.content.cloneNode(true));
    }

    connectedCallback(): void {
        void this.load();
    }

    attributeChangedCallback(_name: string, oldValue: string | null, newValue: string | null): void {
        if (oldValue === newValue) return;
        void this.load();
    }

    /**
     * Re-runs the query. `<food-log>` calls this when the search box is
     * cleared, so a tile logged during this visit is reflected on return.
     */
    async refresh(): Promise<void> {
        await this.load();
    }

    private get mealType(): MealType | null {
        const value = this.getAttribute('meal-type');
        return value && MEAL_TYPES.includes(value as MealType) ? value as MealType : null;
    }

    private async load(): Promise<void> {
        if (!this.isConnected) return;
        const mealType = this.mealType;
        if (!mealType) {
            this.showNothing();
            return;
        }

        const seq = ++this.loadSeq;
        try {
            const entries = await HealthService.fetchFrequentEntries(mealType, TILE_LIMIT);
            if (seq !== this.loadSeq) return;
            this.render(entries);
        } catch (error) {
            if (seq !== this.loadSeq) return;
            this.showError(error);
        }
    }

    private render(entries: FrequentEntry[]): void {
        const shadow = this.shadowRoot!;
        const grid = shadow.getElementById('grid')!;
        shadow.getElementById('error')!.hidden = true;
        grid.hidden = false;
        grid.replaceChildren();

        if (entries.length === 0) {
            this.showNothing();
            return;
        }

        for (const entry of entries) {
            grid.appendChild(this.createTile(entry));
        }
        shadow.getElementById('wrapper')!.hidden = false;
    }

    private createTile(entry: FrequentEntry): HTMLElement {
        const isMeal = entry.kind === 'meal';
        const name = isMeal ? entry.meal.name : entry.item.display_name;
        const imagePath = isMeal ? entry.meal.image_path : entry.item.image_path;

        const tile = document.createElement('button');
        tile.type = 'button';
        tile.className = 'tile';

        const thumb = document.createElement('food-thumb');
        if (imagePath) thumb.setAttribute('path', imagePath);
        thumb.setAttribute('alt', name);
        tile.appendChild(thumb);

        const label = document.createElement('span');
        label.className = 'tile-name';
        if (isMeal) {
            const badge = document.createElement('span');
            badge.className = 'meal-badge';
            badge.textContent = 'Meal';
            label.appendChild(badge);
        }
        label.appendChild(document.createTextNode(name));
        tile.appendChild(label);

        tile.addEventListener('click', () => {
            this.dispatchEvent(entry.kind === 'meal'
                ? createSelectMealEvent(entry.meal)
                : createSelectLibraryItemEvent(entry.item));
        });
        return tile;
    }

    private showNothing(): void {
        const shadow = this.shadowRoot!;
        shadow.getElementById('grid')!.replaceChildren();
        shadow.getElementById('error')!.hidden = true;
        shadow.getElementById('wrapper')!.hidden = true;
    }

    private showError(error: unknown): void {
        const shadow = this.shadowRoot!;
        const errorEl = shadow.getElementById('error')!;
        errorEl.textContent = error instanceof Error ? (error.stack ?? error.message) : String(error);
        errorEl.hidden = false;
        const grid = shadow.getElementById('grid')!;
        grid.replaceChildren();
        grid.hidden = true;
        shadow.getElementById('wrapper')!.hidden = false;
    }
}

if (!customElements.get('frequent-grid')) {
    customElements.define('frequent-grid', FrequentGrid);
}
